const fs = require('fs'), path = require('path'), cp = require('child_process');
const D = process.argv[2] || require('os').tmpdir();
const n = (s) => typeof s === 'string' ? s.split(D).join('<D>') : s;
const er = (e) => e ? `${e.name}|${e.code}|${n(e.message)}` : 'ok';
const t = (l, f) => { try { const r = f(); console.log(l, 'ok', r === undefined ? '' : JSON.stringify(n(r))); } catch (e) { console.log(l, er(e)); } };
const m = (p) => (fs.statSync(p).mode & 0o7777).toString(8);
const W = path.join(D, 'm52'); fs.rmSync(W, { recursive: true, force: true }); fs.mkdirSync(W);
const old = process.umask(0o022);
console.log('umask was', old.toString(8), 'now', process.umask().toString(8));
t('mkdirSync 0o700', () => { fs.mkdirSync(path.join(W, 'd7'), 0o700); return m(path.join(W, 'd7')); });
t('mkdirSync {mode:0o750}', () => { fs.mkdirSync(path.join(W, 'd75'), { mode: 0o750 }); return m(path.join(W, 'd75')); });
t('mkdirSync recursive 0o700', () => { fs.mkdirSync(path.join(W, 'r/a/b'), { recursive: true, mode: 0o700 }); return [m(path.join(W, 'r')), m(path.join(W, 'r/a/b'))].join(','); });
t('writeFileSync mode 0o600', () => { fs.writeFileSync(path.join(W, 'f6'), 'x', { mode: 0o600 }); return m(path.join(W, 'f6')); });
t('openSync wx 0o640', () => { fs.closeSync(fs.openSync(path.join(W, 'f64'), 'wx', 0o640)); return m(path.join(W, 'f64')); });
t('writeFileSync mode 0o777 umask022', () => { fs.writeFileSync(path.join(W, 'f7'), 'x', { mode: 0o777 }); return m(path.join(W, 'f7')); });
process.umask(0o077); t('mkdirSync default umask077', () => { fs.mkdirSync(path.join(W, 'du')); return m(path.join(W, 'du')); });
t('writeFileSync default umask077', () => { fs.writeFileSync(path.join(W, 'fu'), 'x'); return m(path.join(W, 'fu')); });
process.umask(0o022);
fs.writeFileSync(path.join(W, 'src.sh'), '#!/bin/sh\necho cp-ok\n'); fs.chmodSync(path.join(W, 'src.sh'), 0o750);
t('copyFileSync keeps mode', () => { fs.copyFileSync(path.join(W, 'src.sh'), path.join(W, 'dst.sh')); return m(path.join(W, 'dst.sh')); });
t('cpSync keeps mode', () => { fs.cpSync(path.join(W, 'src.sh'), path.join(W, 'dst2.sh')); return m(path.join(W, 'dst2.sh')); });
t('copied script runs', () => cp.execFileSync(path.join(W, 'dst.sh'), { encoding: 'utf8' }).trim());
fs.writeFileSync(path.join(W, 'file'), 'x');
t('mkdirSync recursive on file', () => fs.mkdirSync(path.join(W, 'file'), { recursive: true }));
t('chmodSync NUL', () => fs.chmodSync(path.join(W, 'file') + '\u0000', 0o644));
t('readFileSync NUL', () => fs.readFileSync('a\u0000b'));
t('lchmod', () => [typeof fs.lchmod, typeof fs.lchmodSync, typeof fs.promises.lchmod].join(','));
t('open bad flag missing', () => fs.open(path.join(W, 'nope/x'), 'zz', () => console.log('cb ran')));
t('writeFileSync bad data missing dir', () => fs.writeFileSync(path.join(W, 'nope/x'), 5));
t('mkdirSync bad mode missing', () => fs.mkdirSync(path.join(W, 'nope/x/y'), { mode: 'zz' }));
t('openSync bad mode missing', () => fs.openSync(path.join(W, 'nope'), 'r', 'zz'));
t('versions.node assign', () => { 'use strict'; process.versions.node = 'x'; return process.versions.node; });
t('versions frozen', () => Object.isFrozen(process.versions));
t('ppid assign', () => { process.ppid = 5; return process.ppid === 5; });
